INSERT INTO answers(id, question_id, text, correct) VALUES ('17ec6804-faa0-42e5-8194-4fdf3448c43c','611308f8-334e-4a93-abb7-110bfb4b32a2','Expirado el mandato o en caso de disolución, las Diputaciones Permanentes seguirán ejerciendo sus funciones hasta la constitución de las nuevas Cortes Generales.',true);
