INSERT INTO questions(id, unit_id, text, explanation, difficulty) VALUES ('4442bd88-1125-4cc9-b44c-6b90d30a5f9e','11111111-1111-1111-1111-111111111112','Según el artículo 79, apartado 2, ¿cuál de las siguientes afirmaciones es correcta?','Art. 79','MEDIUM');
