INSERT INTO answers(id, question_id, text, correct) VALUES ('8b6b37c3-13a9-4e54-bcc0-7d77b3deb258','b1939d56-b967-48de-961c-6b76170a2018','Los poderes públicos fomentarán la educación sanitaria, la educación física y el deporte. Asimismo facilitarán la adecuada utilización del ocio.',false);
