INSERT INTO questions(id, unit_id, text, explanation, difficulty) VALUES ('962501f4-e6a9-427f-879d-b91c7737915f','11111111-1111-1111-1111-111111111112','Según el artículo 92, apartado 1, ¿cuál de las siguientes afirmaciones es correcta?','Art. 92','MEDIUM');
